api.look('agent');
const cx = api.w/2;
const k = api.seg(t, 0, 2.4);
api.text('Thread', cx, 90, {size:34, weight:700, k:api.seg(t,0,0.6)});
const n = 14;
for (let i = 0; i < n; i++) {
  const kk = api.stag(t, i, {gap:0.12, dur:0.3, from:0.3});
  const y = 150 + i*36;
  api.rect(cx-150, y - (1-kk)*40, 300, 28, {r:6, c:'a2', fill:'panel', a:kk, w:2});
  api.line(cx-130, y+14-(1-kk)*40, cx-130+api.rand(i)*180+40, y+14-(1-kk)*40, {c:'dim', a:kk, w:3});
}
api.counter(400, cx, 700, {k, suf:' rows', size:48, c:'accent'});
api.say('A thread with 400 rows', 0.3, 3.6);

api.look('agent');
const cx = api.w/2, cy = 380;
const k = api.seg(t, 0, 2.5);
api.shake(t, api.seg(t,3,3.4)*8*(1-api.seg(t,3.4,5)));
// phone outline
api.rect(cx-130, cy-230, 260, 460, {r:34, c:'fg', w:4});
// rows pouring in all at once
const rows = 40;
for (let i = 0; i < rows; i++) {
  const kk = api.clamp(k*1.6 - i/rows*0.6, 0, 1);
  const y = cy-210 + i*10;
  if (y < cy+210) api.rect(cx-110, y, 220, 7, {r:3, c:i%2?'a2':'a3', fill:i%2?'a2':'a3', a:kk*0.9});
}
// memory bar filling
api.text('Memory', cx, 700, {size:20, c:'dim', align:'center'});
const m = api.seg(t, 0.2, 3);
api.progress(cx-130, 715, 260, 22, m, {k:api.seg(t,0,0.5), c: m>0.85?'bad':'warn'});
// crash overlay
const x = api.seg(t, 3.2, 4.2);
if (x > 0) {
  c.save(); c.globalAlpha = 0.85*x; c.fillStyle = '#0b0813'; c.fillRect(cx-130, cy-230, 260, 460); c.restore();
  api.shape('cross', cx, cy-20, 110*api.back(x), {c:'bad', w:10});
  api.text('Crash', cx, cy+80, {size:40, weight:700, c:'bad', align:'center', k:x});
}
api.say('Loading all rows crashed it', 0.4, 5.5);

api.look('agent');
const cx = api.w/2;
const A = api.node(cx, 220, 220, 90, 'Database', {icon:'doc', k:api.seg(t,0,0.8), pop:true});
const B = api.node(cx, 520, 220, 90, 'App', {icon:'phone', k:api.seg(t,0.5,1.3), pop:true});
api.link(A, B, {k:api.seg(t,1.2,2.2), label:'400 rows', flow:t, c:'bad'});
api.swarm(60, t, {mode:'fall', cx, cy:370, rx:30, ry:90, c:'accent', k:api.seg(t,1.4,2.5)});
api.scribble(cx, 520, 140, 60, {k:api.seg(t,3,4), c:'bad'});
api.text('Too much, all at once', cx, 640, {size:24, align:'center', k:api.seg(t,3,3.8)});
api.say('All at once was too much', 0.4, 4.6);

api.look('agent');
const cx = api.w/2;
api.text('Fix: 50 at a time', cx, 90, {size:34, weight:700, align:'center', k:api.seg(t,0,1)});
const pages = 8;
for (let p = 0; p < pages; p++) {
  const kk = api.stag(t, p, {gap:0.35, dur:0.5, from:0.8});
  const x = 40 + (p%4)*86, y = 190 + Math.floor(p/4)*150;
  api.rect(x, y, 74, 110, {r:10, c:'a2', fill:p===0?'a2':'panel', a:kk, w:2});
  api.text('50', x+37, y+68, {size:26, weight:700, align:'center', a:kk, c:p===0?'ink':'fg'});
}
api.brace(40, 470, 350, 470, {k:api.seg(t,3.6,4.4)});
api.text('8 pages of 50', cx, 530, {size:24, align:'center', k:api.seg(t,3.6,4.4), c:'accent'});
api.say('Now it loads fifty at a time', 0.4, 5.6);

api.look('agent');
const cx = api.w/2, cy = 380;
api.rect(cx-130, cy-230, 260, 460, {r:34, c:'fg', w:4});
for (let i = 0; i < 12; i++) {
  const kk = api.stag(t, i, {gap:0.1, dur:0.3, from:0.4});
  api.rect(cx-110, cy-205 + i*34, 220, 26, {r:6, c:'a2', fill:'panel', a:kk, w:2});
}
const m = api.lerp(0.12, 0.2, api.seg(t,0.5,3));
api.text('Memory', cx, 700, {size:20, c:'dim', align:'center'});
api.progress(cx-130, 715, 260, 22, m, {c:'good'});
api.shape('check', cx+100, cy-250, 70*api.back(api.seg(t,2.5,3.3)), {c:'good', w:8});
api.text('Scroll for 50 more', cx, cy+255, {size:20, c:'dim', align:'center', k:api.seg(t,3.5,4.5)});
api.say('Smooth, no crash', 0.4, 5.5);
